const u16 lvl_wcrawl_row[11] = { 250, 265, 284, 249, 261, 271, 288, 251, 253, 250, 251 };
const u8 lvl_wcrawl_col[11] = { 1, 1, 1, 18, 18, 18, 18, 5, 8, 12, 15 };
