#define LVL_WCRAWL_SPR        0x5012  /* lebendig (KA18) */
#define LVL_WCRAWL_SPR_SPENT  0x5015  /* geplatzt, 0 = Grafik bleibt wie sie ist */
#define LVL_WCRAWL_BULLET_SPR 0x8063  /* 0 = gemeinsames Gegner-Projektil */
#define LVL_WCRAWL_MIRROR     1  /* 1 = rechte Wand per H-Flip aus derselben Grafik */
#define LVL_WCRAWL_SHIP_DMG   1
#define LVL_WCRAWL_HEALTH     2
#define LVL_WCRAWL_POINTS     250
#define LVL_WCRAWL_STEP       5  /* 1/16 px je Frame (0.3 px/Frame) */
#define LVL_WCRAWL_CHANCE     77  /* Wuerfel je Frame gegen 0..255 (30 %) */
#define LVL_WCRAWL_WIN_UP     15  /* px, Kriecher ueber der Schiffsmitte */
#define LVL_WCRAWL_WIN_DOWN   5  /* px, Kriecher unter der Schiffsmitte */
