/* ============ Gegner-Feuerverhalten (Original-Mechanik, periodisch & spielerverfolgend) ============ */
/* lvl_spawn_fire_rate[i]: 0 = schiesst nie. Sonst JEDEN Frame einen 8-Bit-Akkumulator um
   (fire_rate % 100) erhoehen (Ueberlauf/Wrap bei 256) - bei Ueberlauf einen Schuss ausloesen
   und den Akkumulator NICHT zuruecksetzen (der Ueberlauf-Rest bleibt stehen). Numerisch also:
     u8 fire_acc;  // pro Spawn-Instanz, Startwert beliebig/zufaellig
     void enemy_fire_tick(entity_t *e) {
         if (lvl_spawn_fire_rate[e->spawn_idx] == 0) return;
         u8 before = e->fire_acc;
         e->fire_acc += lvl_spawn_fire_rate[e->spawn_idx] % 100;     8-Bit-Ueberlauf gewollt   
         if (e->fire_acc < before) {     uebergelaufen -> abfeuern   
             if (lvl_spawn_fire_rate[e->spawn_idx] >= 100)
                 fire_bullet_aimed_at_player(e, LVL_ENEMY_BULLET_SPR, ENEMY_SHOT_SPEED_NGPC);
             else
                 fire_bullet_random_dir(e, LVL_ENEMY_BULLET_SPR, ENEMY_SHOT_SPEED_NGPC);
         }
     }
   Bei >=100 zielt der Schuss auf die AKTUELLE Spielerposition im Abschussmoment (kein
   Vorhalten), bei <100 eine zufaellige Richtung. ENEMY_SHOT_SPEED original = 6px/Tick,
   skaliert (x0.1517) ~ 0,9 NGPC-px/Frame - im Zweifel 1px/Frame verwenden. */
